	public static LayerDefinition createBodyLayer() {
		MeshDefinition meshdefinition = new MeshDefinition();
		PartDefinition mesh = meshdefinition.getRoot();

		PartDefinition root = mesh.addOrReplaceChild("root", CubeListBuilder.create(), PartPose.ZERO);
		PartDefinition ground = root.addOrReplaceChild("ground", CubeListBuilder.create(), PartPose.offset(0.0F, 24.0F, 0.0F));
		buildGround(ground);

		return LayerDefinition.create(meshdefinition, 256, 1024);
	}

